def transform(grid):
    if not grid or not grid[0]:
        return grid

    n_cols = len(grid[0])
    if n_cols <= 2:
        return grid

    seen = set()
    u = []
    for row in grid:
        if row[0] not in seen:
            u.append(row[0])
            seen.add(row[0])

    p = u[::-1]

    result = []
    for row in grid:
        new_r = list(row)
        for j in range(2, n_cols):
            new_r[j] = p[(j - 2) % len(p)]
        result.append(new_r)

    return result
